import type { LocalDate, TimeOfDay } from './dates';
import type { Rotation } from './rotation';
import type { ShiftTemplate } from './template';

/**
 * Input for creating a new shift template (id and archivedAt are generated by store/system).
 */
export type NewShiftTemplate = Omit<ShiftTemplate, 'id' | 'archivedAt'>;

/**
 * Input for creating or updating a shift instance before calculated startsAt/endsAt timestamps.
 */
export interface NewShift {
  readonly date: LocalDate;
  readonly templateId: string | null;
  readonly name: string;
  readonly icon: string;
  readonly color: string;
  readonly isOff: boolean;
  readonly startTime: TimeOfDay;
  readonly endTime: TimeOfDay;
  readonly breakMinutes: number;
  readonly notes: string;
  readonly source: 'manual' | 'rotation_override';
  readonly rotationId: string | null;
  readonly reminderOverride: number[] | null;
}

/**
 * Input for creating a new rotation (id is generated by store/system).
 */
export type NewRotation = Omit<Rotation, 'id'>;
